/**
 * The client as a world frame (code-split: only a frame page loads it).
 *
 * A frame page is the client served at the one frame address, usually
 * inside a page on another origin, and for one source at a time
 * (frameSource.ts). It differs from the client on a page of its own in three
 * ways, all here:
 *
 *  - WHICH WORLDS IT OPENS. Only worlds whose document comes from the source
 *    of the world its own address named when it started. The rule is asked
 *    of the address a world is opened by and again of the address its
 *    document really came from, so a redirect to another source is refused
 *    too. It is fixed at the start: a change to the page's address
 *    afterwards, by anyone, points it at no other source.
 *
 *  - LEAVING FOR ANOTHER SOURCE. The frame never loads a world from another
 *    source. A door or a script that names one becomes a request to the page
 *    around the frame (`open`), which decides and, if it agrees, replaces
 *    this frame with the one for that source. A world on the same source
 *    opens inside the frame as on any page. With no page around it there is
 *    nobody to ask, and the frame's own rule refuses the world.
 *
 *  - WHAT IT REPORTS. That it started, each step of a load, and the entered
 *    world's title and true address, so the page around it can show where
 *    the visitor is. Nothing is read back here; the one request a wrapped
 *    frame takes, to show the client's own settings, is frameMenu.ts's.
 *
 * The page around the frame is whoever embeds it, so every message is posted
 * to any origin and carries nothing a stranger may not see.
 */
import type { NavigationController } from '../navigation/navigationController';
import type { WorldLifecycleEvent } from '../scene/worldSession';
import { MAX_ADDRESS_LENGTH, frameMessage, type FailureReason, type FrameMessage } from './frameMessages';
import { reportFileDrags, reportWalking, type WalkingDocument } from './frameWalking';
import { frameSource, sourceOf, sourceRule } from './frameSource';
import { isImmersiveVrSupported } from '../xr/xrSupport';
import { isWebPageFailure } from '../veml/webPage';

/** The `<meta name>` by which a page says it is a world frame. */
export const WORLD_FRAME_META = 'webverse-frame';

/** True when the page's own markup says it is a world frame. */
export function isWorldFrame(doc: { querySelector(selector: string): unknown }): boolean {
  return doc.querySelector(`meta[name="${WORLD_FRAME_META}"]`) !== null;
}

/**
 * Why a load failed, in the two cases the page around the frame can help
 * with. `refused`: the world's host answered 401 or 403, so the world is one
 * only some people may read, and a frame carries nobody's sign-in.
 * `unreachable`: no answer the frame may read came back, which is what a
 * host that does not allow reads from other origins looks like from here,
 * and also what a host that is down looks like.
 */
export function failureReason(errors: ReadonlyArray<{ kind: string; phase?: string; message: string }>): FailureReason | undefined {
  // The address answered with a web page, not a world: the page around the frame offers the page itself.
  if (isWebPageFailure(errors)) return 'web-page';
  const first = errors[0];
  if (first?.kind !== 'fetch') return undefined;
  if (first.phase === 'network') return 'unreachable';
  return first.phase === 'http' && /\bHTTP 40[13]\b/.test(first.message) ? 'refused' : undefined;
}

/** The slice of `window` a frame needs. `parent` is the window itself when no page is around it. */
export interface FrameWindow {
  location: { hostname: string; origin: string; href: string };
  parent: unknown;
  /** The page's document, for knowing when the visitor is walking; a test may leave it out. */
  document?: WalkingDocument;
}

export interface WorldFrame {
  /** The session's rules for a frame: its own origin as the page's, and the one source it opens. */
  rules: { pageOrigin: string; opens(origin: string): boolean };
  /** `navigation`, with a world on another source asked of the page around the frame instead of loaded. */
  guard(navigation: NavigationController): NavigationController;
  /** Tell the page around the frame of a step in a load. `documentUrl` is where the current document really came from. */
  onLifecycle(event: WorldLifecycleEvent, documentUrl: string | null): void;
}

export function startWorldFrame(win: FrameWindow, vrSupported: () => Promise<boolean> = () => isImmersiveVrSupported()): WorldFrame {
  // The one source this frame document is for, read once. Its own address is no source: it serves the client.
  const named = frameSource(win.location.href);
  const own = named === win.location.origin ? null : named;
  const outer = win.parent === win ? null : (win.parent as { postMessage(message: unknown, targetOrigin: string): void });

  const tell = (message: FrameMessage): void => {
    try {
      outer?.postMessage(frameMessage(message), '*');
    } catch {
      // The page around the frame is gone or refuses: the frame carries on.
    }
  };
  /** Where the document of the world the visitor is in really came from. */
  let here: string | null = null;
  /** `url` in full, or null when it is not an address or too long to send. */
  const full = (url: string, base = win.location.href): string | null => {
    try {
      const href = new URL(url, base).href;
      return href.length <= MAX_ADDRESS_LENGTH ? href : null;
    } catch {
      return null;
    }
  };
  // Whether this frame offers its own Enter VR button: the browser can present immersive VR. Told with each
  // place entered, so the page around the frame can leave room for the button at its bar's end.
  let vr = false;
  const tellStatus = (state: 'loading' | 'entered' | 'failed', address: string, reason?: FailureReason): void => {
    const url = full(address);
    if (url === null) return;
    if (reason) tell({ type: 'status', state, url, reason });
    else tell(state === 'entered' && vr ? { type: 'status', state, url, vr: true } : { type: 'status', state, url });
  };
  void vrSupported().then(
    (yes) => {
      vr = yes;
      // In this page's own console, where whoever wonders why there is no Enter VR button can read it: a
      // browser extension that offers VR to the top page may not offer it inside a frame.
      console.info(`[webverse] frame: immersive-vr supported here: ${yes}`);
      if (yes && here !== null) tellStatus('entered', here);
    },
    () => undefined,
  );
  // Walking is the visitor holding the pointer in the world, or a thumb holding a stick. The page around the
  // frame cannot see either for itself, and wants to know so its own controls can step aside. This page's own
  // controls (its Enter VR button) step aside too, by the mark it puts on itself (framedPage.css).
  if (win.document) {
    const marked = win.document as WalkingDocument & { documentElement?: { toggleAttribute(name: string, on: boolean): void } };
    reportWalking(win.document, (on) => {
      marked.documentElement?.toggleAttribute('data-webverse-walking', on);
      tell({ type: 'walking', on });
    });
    // A file dragged over the world: the page around it puts a place to drop it over the frame.
    reportFileDrags(win.document, () => tell({ type: 'dragging' }));
  }

  tell({ type: 'ready' });

  return {
    rules: { pageOrigin: win.location.origin, opens: sourceRule(own) },

    guard(navigation) {
      return {
        ...navigation,
        navigate(url, opts) {
          // A relative address is the world's own, read against its document
          // as a link's is. The frame page's own address is no world's base:
          // its host serves the client and nothing else.
          const base = here ?? win.location.href;
          const source = sourceOf(url, base);
          // Not a web address: left to fail inside the frame, as on any page.
          if (source === null) return navigation.navigate(url, opts);
          const address = full(url, base);
          // This frame's own source, or nobody to ask: the frame's own business.
          if (outer === null || source === own) return navigation.navigate(address ?? url, opts);
          if (address !== null) tell({ type: 'open', url: address, gesture: opts?.unasked !== true });
          return Promise.resolve(null);
        },
      };
    },

    onLifecycle(event, documentUrl) {
      if (event.kind === 'load-started') tellStatus('loading', event.url);
      else if (event.kind === 'load-failed') tellStatus('failed', event.url, failureReason(event.errors));
      else if (event.kind === 'world-entered') {
        here = full(documentUrl ?? event.url);
        tellStatus('entered', documentUrl ?? event.url);
      } else if (event.kind === 'unloaded') here = null;
      else if (event.kind === 'document-parsed' && event.title !== null) tell({ type: 'title', title: event.title });
    },
  };
}
