/**
 * The source a world frame is for.
 *
 * A world's *source* is the origin its document came from. Every world runs
 * in a frame at the client's one frame address, and a frame document is for
 * one source at a time: the source of the world its own address names when
 * it starts. It opens worlds from that source and no other. A door or a
 * script that names another source is asked of the page around the frame,
 * which puts a new frame document in this one's place, so no two sources'
 * worlds ever run in one document.
 *
 * The frame address is the same for every source, so the browser does not
 * keep one source's worlds from another's: the client does, by keying what
 * a world saves and what a visitor allowed by the world's source.
 */
import { parseWorldUrlHash } from '../navigation/worldUrlHash';

/**
 * The source of the document at `url` (resolved against `base` when
 * relative): its `http:` or `https:` origin. Null for anything else; an
 * address with no origin of its own belongs to no source.
 */
export function sourceOf(url: string, base?: string): string | null {
  try {
    const parsed = new URL(url, base);
    return parsed.protocol === 'https:' || parsed.protocol === 'http:' ? parsed.origin : null;
  } catch {
    return null;
  }
}

/**
 * The source a frame page at `href` is for: the source of the world its
 * fragment names (`#world-url=<address>`). Null when it names none, or
 * names something that is not a web address.
 */
export function frameSource(href: string): string | null {
  let fragment: string;
  try {
    fragment = new URL(href).hash;
  } catch {
    return null;
  }
  const world = parseWorldUrlHash(fragment);
  return world === null ? null : sourceOf(world);
}

/**
 * What a frame for `source` opens: that one origin. A frame for no source
 * opens nothing. The rule is fixed when the frame starts, so nothing that
 * changes the page's address afterwards points it at another source.
 */
export function sourceRule(source: string | null): (origin: string) => boolean {
  return (origin) => source !== null && sourceOf(origin) === origin && origin === source;
}
